python - <<'PY'
from PIL import Image
import numpy as np
from collections import deque
for run in ['initial','controller/align_settle','controller/push_1_settle']:
 root='/app/runs/'+run; a=np.array(Image.open(root+'/last/topview.jpg')); d=np.load(root+'/depth_topview.npy')[0]
 for label,m in [('green',(a[:,:,1]>130)&(a[:,:,0]<80)&(a[:,:,2]<100)),('red',(a[:,:,0]>70)&(a[:,:,1]<25)&(a[:,:,2]<25))]:
  seen=np.zeros(m.shape,bool); comps=[]
  for y,x in zip(*np.where(m&~seen)):
   if seen[y,x]:continue
   q=[(y,x)];seen[y,x]=1; pts=[]
   while q:
    yy,xx=q.pop();pts.append((yy,xx))
    for Y,X in ((yy-1,xx),(yy+1,xx),(yy,xx-1),(yy,xx+1)):
     if 0<=Y<m.shape[0] and 0<=X<m.shape[1] and m[Y,X] and not seen[Y,X]:seen[Y,X]=1;q.append((Y,X))
   if len(pts)>=3:
    ps=np.array(pts); comps.append((len(pts),ps[:,1].mean(),ps[:,0].mean(),(ps[:,1].min(),ps[:,1].max(),ps[:,0].min(),ps[:,0].max())))
  print(run,label,sorted(comps,reverse=True)[:12])
