from PIL import Image
import numpy as np
from collections import deque
root='/app/runs/controller/edge_converge'
for cam in ['front','left','right','topview']:
 a=np.array(Image.open(f'{root}/last/{cam}.jpg'));mask=(a[:,:,0]>75)&(a[:,:,1]<20)&(a[:,:,2]<20)
 H,W=mask.shape;seen=np.zeros(mask.shape,bool);comps=[]
 for y,x in zip(*np.where(mask)):
  if seen[y,x]:continue
  q=[(y,x)];seen[y,x]=1;pts=[]
  while q:
   yy,xx=q.pop();pts.append((yy,xx))
   for Y,X in ((yy-1,xx),(yy+1,xx),(yy,xx-1),(yy,xx+1)):
    if 0<=Y<H and 0<=X<W and mask[Y,X] and not seen[Y,X]:seen[Y,X]=1;q.append((Y,X))
  if len(pts)>15:
   ps=np.array(pts);comps.append((len(pts),tuple(np.round(ps.mean(axis=0)[::-1],1)),(ps[:,1].min(),ps[:,1].max(),ps[:,0].min(),ps[:,0].max())))
 print(cam,sorted(comps,reverse=True)[:30])
